def simulate_prs(step, terminal, energy, initial_state, max_steps=None):
    s = initial_state
    bound = max_steps if max_steps else energy(s) + 1
    trace = [energy(s)]
    for i in range(bound):
        if terminal(s): return (s, i, trace, True)
        s_next = step(s)
        assert energy(s_next) < trace[-1]
        s = s_next
        trace.append(energy(s))
    return (s, bound, trace, terminal(s))

def stratified_step(energies, level, decrease):
    result = list(energies)
    result[level] -= decrease
    for j in range(level):
        result[j] += decrease
    return result

def euclid_prs(a, b):
    steps = 0
    trace = [b]
    while b > 0:
        a, b = b, a % b
        steps += 1
        trace.append(b)
    return (a, steps, trace)
